//! The text of the two generated files. Parsing is the parent module's; nothing here reads a file.

use super::{Act, Row};

/// A line, newline included. A file is lines in order and ends in one newline.
fn line(out: &mut String, text: &str) {
    out.push_str(text);
    out.push('\n');
}

/// A Rust string literal. Only what a literal cannot hold raw is escaped, and a control character is
/// written as a `\u{..}` escape.
pub(super) fn rust_str(value: &str) -> String {
    let mut out = String::from("\"");
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// `Some("x")`, or `None` for a blank: a blank is a gap in the registry, never a default.
fn option(value: &str) -> String {
    if value.is_empty() {
        "None".into()
    } else {
        format!("Some({})", rust_str(value))
    }
}

/// `list and detail` becomes `ListAndDetail`.
pub(super) fn variant(words: &str) -> String {
    words
        .split(|c: char| c.is_whitespace() || c == '_' || c == '-')
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().chain(chars).collect::<String>(),
                None => String::new(),
            }
        })
        .collect()
}

/// `list and detail` becomes `list-and-detail`: each run of whitespace is one dash.
pub(super) fn context(scope: &str) -> String {
    scope.split_whitespace().collect::<Vec<_>>().join("-")
}

const VOCABULARY_HEAD: &str = r#"// GENERATED by `cargo xtask verify-vocabulary --write`. Do not hand-edit.
//
// The verb, the glyph and the status token each variant renders as, from
// `crates/core-model/domain/enum-verbs.toml`.
//
// `None` is a gap in the registry, not a default, and every one is listed in `GAPS`.

#![allow(dead_code)]

/// How one variant reads. `None` where the registry carries no answer.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rendering {
    pub verb: Option<&'static str>,
    /// A name in `packages/icons/icons/`, which is a lucide name.
    pub glyph: Option<&'static str>,
    /// The token stem without its `--status-` prefix.
    pub badge_status: Option<&'static str>,
    /// The token, such as `--status-running`.
    pub status_token: Option<&'static str>,
    /// The sentence a tooltip reads where the verb alone gives no reasoning.
    pub hint: Option<&'static str>,
}

"#;

const VOCABULARY_LOOKUP: &str = r#"/// One variant of one vocabulary. `None` where this build has never heard of it.
pub fn rendering(vocabulary: &str, variant: &str) -> Option<&'static Rendering> {
    let (_, rows) = VOCABULARIES.iter().find(|(name, _)| *name == vocabulary)?;
    rows.iter().find(|(wire, _)| *wire == variant).map(|(_, rendering)| rendering)
}

/// A variant the registry has no sanctioned copy, glyph or hue for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Gap {
    pub vocabulary: &'static str,
    pub variant: &'static str,
    pub missing: &'static [&'static str],
}

"#;

/// `vocabulary.rs`: the wanted vocabularies, then the lookup, then every gap.
pub fn vocabulary(vocabularies: &[(&str, Vec<Row>)]) -> String {
    let mut out = String::from(VOCABULARY_HEAD);
    let mut gaps = Vec::new();
    for (name, rows) in vocabularies {
        line(&mut out, &format!("/// `{name}`, keyed by the wire value."));
        line(
            &mut out,
            &format!("pub const {}: &[(&str, Rendering)] = &[", name.to_uppercase()),
        );
        for row in rows {
            let mut missing = Vec::new();
            if row.verb.is_empty() {
                missing.push("verb");
            }
            if row.glyph.is_empty() {
                missing.push("icon");
            }
            if row.token.is_empty() {
                missing.push("token");
            }
            if !missing.is_empty() {
                gaps.push((name, &row.variant, missing));
            }
            line(
                &mut out,
                &format!(
                    "    ({}, Rendering {{ verb: {}, glyph: {}, badge_status: {}, status_token: {}, hint: {} }}),",
                    rust_str(&row.variant),
                    option(&row.verb),
                    option(&row.glyph),
                    option(&row.stem),
                    option(&row.token),
                    option(&row.hint),
                ),
            );
        }
        line(&mut out, "];");
        line(&mut out, "");
    }
    line(&mut out, "/// Every vocabulary, by the name `enum-verbs.toml` gives it.");
    line(
        &mut out,
        "pub const VOCABULARIES: &[(&str, &[(&str, Rendering)])] = &[",
    );
    for (name, _) in vocabularies {
        line(
            &mut out,
            &format!("    ({}, {}),", rust_str(name), name.to_uppercase()),
        );
    }
    line(&mut out, "];");
    line(&mut out, "");
    out.push_str(VOCABULARY_LOOKUP);
    line(&mut out, "pub const GAPS: &[Gap] = &[");
    for (name, variant, missing) in gaps {
        let missing: Vec<String> = missing.iter().map(|m| rust_str(m)).collect();
        line(
            &mut out,
            &format!(
                "    Gap {{ vocabulary: {}, variant: {}, missing: &[{}] }},",
                rust_str(name),
                rust_str(variant),
                missing.join(", ")
            ),
        );
    }
    line(&mut out, "];");
    out
}

const ACTIONS_HEAD: &str = r#"// GENERATED by `cargo xtask verify-vocabulary --write`. Do not hand-edit.
//
// Every act Bridge offers: what it is called, what it is bound to, and the glyph it draws or
// why it draws none. From `crates/core-model/domain/actions.toml`.
//
// A Motion is here and is not an act: it moves the cursor, appears in no palette, and
// `in_palette` is false for it. `unbuilt` names the issue that answers the key, on a row
// Bridge cannot answer yet.

#![allow(dead_code)]

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ActionKind {
    Action,
    Motion,
}

/// Modifier-based and working anywhere, or single-key and on what is focused.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ActionTier {
    Global,
    Contextual,
}

/// Why an act's glyph column is empty.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IconAbsence {
    Undecided,
    ByDesign,
}

/// Where the binding is offered: the registry's own set, read off the rows.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ActionScope {
"#;

const ACTIONS_STRUCT: &str = r#"#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Act {
    /// The id an implementation binds to. The registry's table key.
    pub id: &'static str,
    pub kind: ActionKind,
    pub tier: ActionTier,
    /// What a person reads, in the lexicon's word. Never the id.
    pub verb: &'static str,
    /// A name in `packages/icons/icons/`, or `None`, in which case `icon_absent` says why.
    pub glyph: Option<&'static str>,
    pub icon_absent: Option<IconAbsence>,
    /// The binding, spelled as the contract's map spells it.
    pub shortcut: &'static str,
    pub scope: ActionScope,
    pub destructive: bool,
    pub confirms: bool,
    /// The issue that gives the binding an act, on a row nothing answers yet.
    pub unbuilt: Option<&'static str>,
    /// Whether the command palette lists it: every Action, and no Motion.
    pub in_palette: bool,
}

/// The map, in the registry's order: global first, then contextual.
pub const ACTIONS: &[Act] = &[
"#;

const ACTIONS_TAIL: &str = r#"/// One act, by the id an implementation binds to. `None` for an id this build has never heard of.
pub fn act(id: &str) -> Option<&'static Act> {
    ACTIONS.iter().find(|act| act.id == id)
}
"#;

/// `actions.rs`: the enums, the scope set read off the rows, then the map.
pub fn actions(acts: &[Act]) -> String {
    // The scopes are read off the rows rather than listed here: a scope is where a binding is
    // offered and the registry decides that.
    let mut scopes: Vec<&str> = acts.iter().map(|act| act.scope.as_str()).collect();
    scopes.sort_unstable();
    scopes.dedup();

    let mut out = String::from(ACTIONS_HEAD);
    for scope in &scopes {
        line(&mut out, &format!("    {},", variant(scope)));
    }
    line(&mut out, "}");
    line(&mut out, "");
    line(&mut out, "impl ActionScope {");
    line(&mut out, "    /// The registry's spelling.");
    line(&mut out, "    pub const fn as_str(self) -> &'static str {");
    line(&mut out, "        match self {");
    for scope in &scopes {
        line(
            &mut out,
            &format!("            ActionScope::{} => {},", variant(scope), rust_str(scope)),
        );
    }
    line(&mut out, "        }");
    line(&mut out, "    }");
    line(&mut out, "");
    line(
        &mut out,
        "    /// The key context a screen sets on the element whose keys these are, such as `list-and-detail`.",
    );
    line(
        &mut out,
        "    /// `None` for `anywhere`: those keys are bound with no context.",
    );
    line(
        &mut out,
        "    pub const fn key_context(self) -> Option<&'static str> {",
    );
    line(&mut out, "        match self {");
    for scope in &scopes {
        let key = if *scope == "anywhere" {
            "None".to_string()
        } else {
            format!("Some({})", rust_str(&context(scope)))
        };
        line(&mut out, &format!("            ActionScope::{} => {key},", variant(scope)));
    }
    line(&mut out, "        }");
    line(&mut out, "    }");
    line(&mut out, "}");
    line(&mut out, "");
    out.push_str(ACTIONS_STRUCT);
    for act in acts {
        line(&mut out, "    Act {");
        line(&mut out, &format!("        id: {},", rust_str(&act.id)));
        line(&mut out, &format!("        kind: ActionKind::{},", act.kind));
        line(&mut out, &format!("        tier: ActionTier::{},", act.tier));
        line(&mut out, &format!("        verb: {},", rust_str(&act.verb)));
        line(&mut out, &format!("        glyph: {},", option(&act.icon)));
        let absent = if act.absent.is_empty() {
            "None".to_string()
        } else {
            format!("Some(IconAbsence::{})", variant(&act.absent))
        };
        line(&mut out, &format!("        icon_absent: {absent},"));
        line(&mut out, &format!("        shortcut: {},", rust_str(&act.shortcut)));
        line(&mut out, &format!("        scope: ActionScope::{},", variant(&act.scope)));
        line(&mut out, &format!("        destructive: {},", act.destructive));
        line(&mut out, &format!("        confirms: {},", act.confirms));
        let unbuilt = match act.issue {
            Some(n) => format!("Some({})", rust_str(&format!("#{n}"))),
            None => "None".to_string(),
        };
        line(&mut out, &format!("        unbuilt: {unbuilt},"));
        line(&mut out, &format!("        in_palette: {},", act.kind == "Action"));
        line(&mut out, "    },");
    }
    line(&mut out, "];");
    line(&mut out, "");
    out.push_str(ACTIONS_TAIL);
    out
}
